    for (int i = 0; i < 26 && (*buffer_index) < max_words; i++) {
        if (trie->children[i] == NULL) {
            continue;
        }
        prefix[prefix_len] = i + 'a';
        trie_collect_words_helper(trie->children[i], prefix, prefix_len + 1,
                                   buffer, buffer_index, max_words);
    }
}

